out = {}
files = ["data/a.txt", "data/b.txt", "data/ignore.md"]
for f in files:
    c = repo.read(f)
    lines = c.split("\n") if c else []
    sl = c.splitlines() if c else []
    blank = 0
    for l in sl:
        if l.strip() == "":
            blank += 1
    out[f] = {
        "repr": repr(c),
        "ends_with_newline": c.endswith("\n") if c else None,
        "split_newline_count": len(lines),
        "splitlines_count": len(sl),
        "blank_lines": blank,
    }
result(out)

